// Reviewed beginner lessons. Stable IDs preserve existing course and review progress.
const p=(jp,role,note)=>({jp,role:role==='verb'?'action':role,note});
const ex=(scene,parts,zh)=>({scene,parts,zh});
const c=(id,use,context,options,answers,why,wrong)=>({id,type:'choice',use,context,options,answers,why,wrong});
const b=(id,use,context,parts,translation,why,otherOrders=[])=>({id,type:'build',use,context,parts,translation,why,hint:why,orders:[parts.map((_,i)=>i),...otherOrders]});
const f=(id,use,context,source,prefix,options,answers,translation,why,wrong)=>({id,type:'transform',use,context,source,prefix,options,answers,translation,why,wrong});
